	}
	if !reflect.DeepEqual(recordsAfter, recordsBefore) || cpAfter != cpBefore {
		t.Fatalf("Access calls altered the audit chain: before (%d records, %+v), after (%d records, %+v)",
			len(recordsBefore), cpBefore, len(recordsAfter), cpAfter)
	}

